exercises.solution:
const vendas = [
  { cliente: 'Dona Lurdes', valor: 120, paga: true },
  { cliente: 'Seu Jorge', valor: 60, paga: false },
  { cliente: 'Marta', valor: 90, paga: true },
  { cliente: 'Caio', valor: 40, paga: false },
  { cliente: 'Renata', valor: 100, paga: true },
];

const pagas = vendas.filter((venda) => venda.paga);
const soma = pagas.reduce((total, venda) => total + venda.valor, 0);
const media = soma / pagas.length;

console.log('Vendas pagas:', pagas.length);
console.log('Total recebido:', soma);
console.log('Média por venda:', media.toFixed(2));

